function createCircleChart(e, t, a, s) {
    return `<svg class="mkc_circle-chart" viewbox="0 0 36 36" width="${a}" height="${a}" xmlns="http://www.w3.org/2000/svg">
        <path class="mkc_circle-bg" stroke="#eeeeee" stroke-width="${.5*s}" fill="none" d="M18 2.0845
              a 15.9155 15.9155 0 0 1 0 31.831
              a 15.9155 15.9155 0 0 1 0 -31.831"/>
        <path class="mkc_circle" stroke="${t}" stroke-width="${s}" stroke-dasharray="${e},100" stroke-linecap="round" fill="none"
            d="M18 2.0845
              a 15.9155 15.9155 0 0 1 0 31.831
              a 15.9155 15.9155 0 0 1 0 -31.831" />
        <text class="mkc_info" x="50%" y="50%" alignment-baseline="central" text-anchor="middle" font-size="8">${e}%</text>
    </svg>`
}
let charts = document.getElementsByClassName("mkCharts");
for (let c = 0; c < charts.length; c++) {
    let e = charts[c],
        t = e.dataset.percent,
        a = "color" in e.dataset ? e.dataset.color : "#2F4F4F",
        s = "size" in e.dataset ? e.dataset.size : "100",
        r = "stroke" in e.dataset ? e.dataset.stroke : "1";
    charts[c].innerHTML = createCircleChart(t, a, s, r)
}